package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_equals_TriageGen1Test {













    @Test
    public void testEquals_NaN_OneNaN_OneNotNaN() {
        Complex c1 = new Complex(Double.NaN, Double.NaN);
        Complex c2 = new Complex(1.0, 1.0);

        // In the provided code: if (c.isNaN) return isNaN;
        // If c2 is NaN, it returns c1.isNaN (true). 
        // If c1 is NaN, it returns c1.isNaN (true).
        // Wait, looking at the logic:
        // if (c.isNaN) { return isNaN; }
        // This means if the OTHER is NaN, it returns the current object's isNaN status.

        assertTrue("If other is NaN, returns this.isNaN", c2.equals(c1));
        assertFalse("If other is NaN, returns this.isNaN (where this is not NaN)", c2.equals(c1) == false); 
        // Re-evaluating the logic provided in the snippet:
        // if (c.isNaN) { return isNaN; }
        // If c is NaN, it returns the 'isNaN' field of 'this'.

        Complex notNaN = new Complex(1.0, 1.0);
        Complex nan = new Complex(Double.NaN, Double.NaN);

        assertTrue("If other is NaN, result is this.isNaN", notNaN.equals(nan) == false);
        assertTrue("If other is NaN, result is this.isNaN", nan.equals(notNaN) == true);
    }


}

package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_equals_TriageGen1Test {















    @Test
    public void testEquals_NaN_LogicCheck() {
        // Testing the specific branch logic: if (c.isNaN) return isNaN;
        Complex nan1 = new Complex(Double.NaN, Double.NaN);
        Complex nan2 = new Complex(Double.NaN, Double.NaN);
        Complex normal = new Complex(1.0, 1.0);

        // Case: c.isNaN is true. Returns this.isNaN.
        assertTrue("nan1.equals(nan2) -> c.isNaN is true, returns nan1.isNaN (true)", nan1.equals(nan2));
        assertFalse("normal.equals(nan1) -> c.isNaN is true, returns normal.isNaN (false)", normal.equals(nan1));
        assertTrue("nan1.equals(normal) -> c.isNaN is false, goes to real/imag check. NaN != 1.0", !nan1.equals(normal));
    }
}
